 CREATE OR REPLACE VIEW inventory_dashboard_view AS                                                                                      +
  SELECT p.id,                                                                                                                           +
     p.name,                                                                                                                             +
     p.sku,                                                                                                                              +
     p.branch_id,                                                                                                                        +
     p.is_shared,                                                                                                                        +
     p.is_active,                                                                                                                        +
     p.min_stock_level,                                                                                                                  +
     COALESCE(i.quantity, p.stock_quantity, 0) AS current_stock,                                                                         +
     COALESCE(p.selling_price, p.unit_price, (0)::numeric) AS retail_price,                                                              +
     COALESCE(p.cost_price, (0)::numeric) AS cost_price,                                                                                 +
         CASE                                                                                                                            +
             WHEN (COALESCE(i.quantity, p.stock_quantity, 0) = 0) THEN 'out_of_stock'::text                                              +
             WHEN (COALESCE(i.quantity, p.stock_quantity, 0) <= COALESCE(p.min_stock_level, 5)) THEN 'low_stock'::text                   +
             ELSE 'in_stock'::text                                                                                                       +
         END AS stock_status,                                                                                                            +
     ((COALESCE(i.quantity, p.stock_quantity, 0))::numeric * COALESCE(p.selling_price, p.unit_price, (0)::numeric)) AS item_retail_value,+
     ((COALESCE(i.quantity, p.stock_quantity, 0))::numeric * COALESCE(p.cost_price, (0)::numeric)) AS item_cost_value                    +
    FROM (lats_products p                                                                                                                +
      LEFT JOIN inventory i ON (((p.id = i.product_id) AND (i.branch_id = p.branch_id))));;
